scripts.run-tests:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'run-tests',
  description:
    'Run the project test command via run_package_script. Stamps {passed: boolean, summary: string}.',
  inputs: {
    scriptName: {
      type: 'string',
      description: 'Override the npm script name. Defaults to "test".',
      default: 'test',
    },
  },
  outputs: {
    passed: { type: 'boolean', description: 'True iff the test command exited 0.' },
    summary: { type: 'string', description: 'Last ~2KB of stdout/stderr.' },
  },
  requires: ['workspace.read'],
});

interface PackageScriptResult {
  exitCode: number;
  stdout?: string;
  stderr?: string;
}

async function main(): Promise<void> {
  const input = gezel.input as { scriptName?: string };
  const scriptName = input.scriptName ?? 'test';
  const raw = await gezel.mcp.call('run_package_script', { script: scriptName });
  let parsed: PackageScriptResult | null = null;
  if (typeof raw === 'string') {
    try {
      parsed = JSON.parse(raw) as PackageScriptResult;
    } catch {
      // The MCP tool returns a text blob, not always JSON. We treat
      // "non-zero exit code" / "failed" / "FAIL " markers as failure.
    }
  }
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const looksFailed =
    parsed?.exitCode !== undefined
      ? parsed.exitCode !== 0
      : /(?:^|\b)(?:fail|error|exit code [1-9]|✗)\b/i.test(text);
  const tail = text.length > 2048 ? text.slice(-2048) : text;
  gezel.log(`pnpm ${scriptName}: ${looksFailed ? 'failed' : 'passed'}`);
  gezel.output({ passed: !looksFailed, summary: tail });
}

await main();

scripts.open-pr:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'open-pr',
  description:
    'Open a pull request for the current branch via the GitHub MCP tools. Stamps {number, url} on success.',
  inputs: {
    title: { type: 'string', description: 'PR title. Falls back to a derived placeholder.' },
    body: { type: 'string', description: 'PR body. Markdown.' },
    head: {
      type: 'string',
      description: 'Source branch. Defaults to the current branch (caller must resolve).',
      required: true,
    },
    base: { type: 'string', description: 'Target branch.', default: 'main' },
    draft: { type: 'boolean', description: 'Open as draft.', default: false },
  },
  outputs: {
    number: { type: 'number', description: 'Created PR number.' },
    url: { type: 'string', description: 'PR URL.' },
  },
  requires: ['network'],
});

async function main(): Promise<void> {
  const input = gezel.input as {
    title?: string;
    body?: string;
    head: string;
    base?: string;
    draft?: boolean;
  };
  const title = input.title ?? `Ship: ${input.head}`;
  const args: Record<string, unknown> = {
    title,
    head: input.head,
    base: input.base ?? 'main',
  };
  if (input.body) args.body = input.body;
  if (input.draft !== undefined) args.draft = input.draft;
  const raw = await gezel.mcp.call('github_pr_create', args);
  const text = typeof raw === 'string' ? raw : '';
  const m = /Opened PR #(\d+) — (\S+)/.exec(text);
  if (!m) {
    throw new Error(`unexpected github_pr_create response: ${text.slice(0, 200)}`);
  }
  gezel.output({ number: Number(m[1]), url: m[2]! });
}

await main();

scripts.wait-checks:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'wait-checks',
  description:
    'Poll github_check_status for a ref until it settles. Returns {state: success|failure|pending|timeout, checks[]}.',
  inputs: {
    ref: { type: 'string', description: 'Branch name or commit sha.', required: true },
    timeoutMs: {
      type: 'number',
      description: 'How long to wait before giving up.',
      default: 600_000,
      integer: true,
    },
    pollIntervalMs: {
      type: 'number',
      description: 'How long between polls.',
      default: 15_000,
      integer: true,
    },
  },
  outputs: {
    state: { type: 'string', description: 'Final state: success / failure / timeout.' },
    checks: { type: 'array', description: 'Per-check breakdown.', itemType: 'object' },
  },
  requires: ['network'],
});

interface CheckBlock {
  name: string;
  status: string;
  conclusion: string | null;
  url?: string;
}

function parseChecks(text: string): { state: string; checks: CheckBlock[] } {
  const lines = text.split('\n');
  const stateLine = lines[0] ?? '';
  const stateMatch = /^State:\s*(\w+)/i.exec(stateLine);
  const state = stateMatch?.[1]?.toLowerCase() ?? 'unknown';
  const checks: CheckBlock[] = [];
  for (let i = 1; i < lines.length; i++) {
    const m = /^• (.+?) — (\S+?)(?:\s*\/\s*(\S+))?$/.exec(lines[i] ?? '');
    if (!m) continue;
    checks.push({
      name: m[1]!,
      status: m[2]!,
      conclusion: m[3] ?? null,
    });
  }
  return { state, checks };
}

async function main(): Promise<void> {
  const input = gezel.input as { ref: string; timeoutMs?: number; pollIntervalMs?: number };
  const deadline = Date.now() + (input.timeoutMs ?? 600_000);
  const poll = input.pollIntervalMs ?? 15_000;
  let lastState = 'unknown';
  let lastChecks: CheckBlock[] = [];
  while (Date.now() < deadline) {
    const raw = await gezel.mcp.call('github_check_status', { ref: input.ref });
    const text = typeof raw === 'string' ? raw : '';
    const parsed = parseChecks(text);
    lastState = parsed.state;
    lastChecks = parsed.checks;
    gezel.log(`checks for ${input.ref}: ${parsed.state} (${parsed.checks.length} check(s))`);
    if (parsed.state === 'success' || parsed.state === 'failure') {
      gezel.output({ state: parsed.state, checks: parsed.checks });
      return;
    }
    await new Promise((r) => setTimeout(r, poll));
  }
  gezel.output({ state: 'timeout', checks: lastChecks });
}

await main();
